\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{algorithmic}
\usepackage{algorithm}

\title{Cache Replacement Policies: Recitation Notes}
\author{R.~Halvorsen}
\date{Spring 2026}

\begin{document}
\maketitle

\section{Why Replacement Matters}
A cache earns its keep only when the line it evicts is colder than the
line it keeps, so the eviction rule is the whole policy.
This recitation walks through the two classic rules and how to
hand-simulate them on a four-line cache.

\section{Least Recently Used}
LRU evicts the line whose last use is oldest.
A timestamp per line is enough for a teaching implementation.

\begin{algorithm}[t]
\caption{LRU eviction}
\label{alg:lru}
\begin{algorithmic}
\STATE stamp every accessed line with the current time
\IF{the cache is full}
\STATE evict the line with the oldest timestamp
\ENDIF
\STATE insert the new line and stamp it
\end{algorithmic}
\end{algorithm}

\section{Least Frequently Used}
LFU keeps a counter per line instead of a timestamp, so a line that was
hot last week can survive a cold morning.

\begin{algorithm}[t]
\caption{LFU eviction}
\label{alg:lfu}
\begin{algorithmic}
\STATE increment the counter of the accessed line
\IF{the cache is full}
\STATE evict the line with the smallest counter
\ENDIF
\STATE insert the new line with counter one
\end{algorithmic}
\end{algorithm}

\section{Comparing the Two}
LRU follows recency and LFU follows frequency; neither dominates on all
traces, which is why real caches approximate both.
\end{document}

